  "pr.pfintro": "મહિનાની સેલેરી સ્લિપમાંથી EPFO unified portal માટેની ECR ટેક્સ્ટ ફાઇલ અને ચલણની રકમ બને છે. પહેલાં સ્લિપ બનાવો (Salary ટેબ); સ્લિપ વગરના કર્મચારી નીચે લિસ્ટમાં છે.",
  "pr.unver_pf": "અપલોડ કરતાં પહેલાં ચેક કરો: આ બનાવ્યું ત્યારે (14 Nov 2026) EPFO નો પોતાનો ફાઇલ-સ્ટ્રક્ચર દસ્તાવેજ ખૂલી શક્યો નહીં. 11 ફીલ્ડ અને તેનો ક્રમ પેરોલ સૉફ્ટવેર બનાવનારાઓ પ્રકાશિત કરે છે તે પ્રમાણે છે. ફાઇલ EPFO પોર્ટલના ECR પેજ પર અપલોડ કરો; પોર્ટલ કોઈ લાઇન નકારે તો કારણ જણાવે છે.",
