  "it.m_past": "આ વર્ષ પૂરું થઈ ગયું છે. 31 March પછી ભરેલો એડવાન્સ ટેક્સ તેના માટે એડવાન્સ ટેક્સ ગણાતો નથી; નીચેનું વ્યાજ બતાવે છે કે ઘટ કેટલી મોંઘી પડે છે.",
  "it.m_season": "અંદાજ અત્યાર સુધીના નફાને સીધી લીટીમાં આખા વર્ષ સુધી લઈ જાય છે. તમારો બિઝનેસ સીઝનલ હોય તો વર્ષ માટે તમારો પોતાનો આંકડો લખો.",
