  "it.basis": "આ આંકડા શેના પર આધારિત છે ({d} મુજબ)",
  "it.b1": "દર ({d} મુજબ), ટેક્સ વર્ષ 2026-27: નવું રીજીમ ₹4 લાખ સુધી શૂન્ય, ₹8 લાખ સુધી 5%, ₹12 લાખ સુધી 10%, ₹16 લાખ સુધી 15%, ₹20 લાખ સુધી 20%, ₹24 લાખ સુધી 25%, તેથી વધુ 30%; ₹12 લાખ સુધીની આવક પર ટેક્સ ન લાગે તેવી રિબેટ, તેથી થોડું ઉપર માર્જિનલ રિલીફ સાથે; પગાર પર સ્ટાન્ડર્ડ ડિડક્શન ₹75,000. જૂનું રીજીમ: ₹2.5 લાખ સુધી શૂન્ય (60 વર્ષે ₹3 લાખ, 80 વર્ષે ₹5 લાખ), ₹5 લાખ સુધી 5%, ₹10 લાખ સુધી 20%, તેથી વધુ 30%; ₹5 લાખ સુધી રિબેટ ₹12,500; સ્ટાન્ડર્ડ ડિડક્શન ₹50,000. આ દર સેલેરી સ્લિપ ટૂલ પહેલેથી વાપરે છે; આ બિલ્ડમાં Finance Act માંથી ફરી વાંચ્યા નથી, એટલે ચેક કરો.",
  "it.b2": "એડવાન્સ ટેક્સ (Income-tax Act 2025, sections 403 થી 408): TDS પછીનો ટેક્સ ₹10,000 કે વધુ હોય ત્યારે ભરવાનો; 15 June સુધી 15%, 15 September સુધી 45%, 15 December સુધી 75%, 15 March સુધી બધો; પ્રિઝમ્પ્ટિવ કરદાતા 15 March સુધી બધો ભરે છે; 31 March સુધીનું પેમેન્ટ વર્ષ માટે ગણાય છે; 60 કે વધુ ઉંમરના બિઝનેસ આવક વગરના રહેવાસીને છૂટ છે.",
  "it.b3": "વ્યાજ: section 424 (જૂનું 234B) એટલે 90% થી ઓછો ટેક્સ ભર્યો હોય ત્યારે ઘટ પર મહિને કે મહિનાના ભાગે 1%; section 425 (જૂનું 234C) એટલે પહેલા ત્રણ હપ્તામાંથી દરેકની ઘટ પર 3% (15 June સુધી 12% અને 15 September સુધી 36% ભર્યા હોય તો નહીં) અને March ની ઘટ પર 1%.",
  "it.b5": "ચોપડાનો નફો ટેક્સેબલ નફો નથી: Act મુજબનું ડેપ્રિસિએશન, નામંજૂર ખર્ચ અને પ્રિઝમ્પ્ટિવ નિયમો તેને બદલે છે. આ પ્લાન અને ડેટા શીટ તમારા એકાઉન્ટન્ટને આપો.",
  "it.b6": "ગણાયું નથી: સરચાર્જ, ખાસ દરે કેપિટલ ગેઇન, વિદેશી ટેક્સ રાહત, સગીરની આવક પર ટેક્સ, અને મોડા ફાઇલિંગ પરનું વ્યાજ.",
  "it.b7": "કંઈ ફાઇલ થતું નથી અને તમારા ચોપડામાં કંઈ પોસ્ટ થતું નથી.",
  "it.itr_h": "કયું રિટર્ન ફોર્મ બંધબેસે છે, કેમ, અને કયા કાગળ તૈયાર રાખવા તે જોવા થોડા સવાલના જવાબ આપો.",
