  "it.formd_ITR-1": "પગાર કે પેન્શન, બે સુધી મકાન મિલકત અને વ્યાજ જેવા બીજા સ્ત્રોત, અને ₹50 લાખ સુધીની કુલ આવકવાળા રહેવાસી વ્યક્તિ માટે.",
  "it.formd_ITR-2": "બિઝનેસ કે પ્રોફેશનની આવક વગરના વ્યક્તિ કે HUF માટે જેને કેપિટલ ગેઇન, ₹50 લાખથી વધુ આવક, બેથી વધુ મકાન મિલકત, વિદેશી મિલકત કે આવક હોય, કે જે ITR-1 માં બંધબેસતા ન હોય.",
  "it.formd_ITR-3": "પ્રિઝમ્પ્ટિવ સ્કીમમાં ન હોય તેવી બિઝનેસ કે પ્રોફેશનની આવકવાળા વ્યક્તિ કે HUF, ફર્મના ભાગીદાર, કે ITR-4 માં બંધબેસતા ન હોય તે બધા માટે.",
  "it.formd_ITR-4": "પ્રિઝમ્પ્ટિવ બિઝનેસ આવક, ₹50 લાખ સુધીની કુલ આવક, પગાર કે પેન્શન, બે સુધી મકાન મિલકત અને બીજા સ્ત્રોતવાળા રહેવાસી વ્યક્તિ કે HUF માટે.",
  "it.formd_ITR-5": "ફર્મ, LLP, વ્યક્તિઓના સંગઠન (AOP) અને વ્યક્તિઓના સમૂહ (BOI) માટે.",
  "it.formd_ITR-6": "ધર્માદા કે ધાર્મિક હેતુ માટે છૂટ માગતી કંપનીઓ સિવાયની કંપનીઓ માટે.",
  "it.formd_ITR-7": "ટ્રસ્ટ, સંસ્થા, રાજકીય પક્ષ અને એવા લોકો માટે.",
