  "it.w_huf": "ITR-1 ફક્ત વ્યક્તિ માટે છે; બિઝનેસ આવક વગરનું HUF ITR-2 ફાઇલ કરે છે.",
  "it.w_pres2": "તમારા બીજા જવાબોથી ITR-4 ન ચાલે, એટલે બિઝનેસ આવક ITR-3 માં જાય છે.",
  "it.w_pres": "સાદી બીજી આવક સાથે પ્રિઝમ્પ્ટિવ બિઝનેસ આવક ITR-4 માં બંધબેસે છે.",
  "it.w_simple": "ફક્ત પગાર, મકાન મિલકત અને વ્યાજ, મર્યાદાની અંદર, ITR-1 માં બંધબેસે છે.",
  "it.n_forms": "શરતો 31 March 2026 એ પૂરા થયેલા વર્ષ માટે જાહેર થયેલા રિટર્ન પ્રમાણે છે (ટેક્સ પોર્ટલ જણાવે છે તેમ, ITR-1 અને ITR-4 હવે બે સુધી મકાન મિલકતની છૂટ આપે છે). ટેક્સ વર્ષ 2026-27 નાં રિટર્ન હજી Income-tax Rules, 2026 હેઠળ જાહેર થવાનાં બાકી છે: ફાઇલ કરતાં પહેલાં ફોર્મની પોતાની, કોણ વાપરી ન શકે તેની યાદી વાંચો.",
  "it.n_ltcg": "લિસ્ટેડ શેર કે ઇક્વિટી ફંડ પરના નાના લાંબા ગાળાના ગેઇન કેટલાંક વર્ષોમાં ITR-1 અને ITR-4 માં ચાલતા હતા; 2026-27 માટે આની ખાતરી થઈ નથી, એટલે ITR-2 સલામત પસંદગી છે અને ફોર્મની પોતાની યાદી નક્કી કરે છે.",
  "it.n_ae": "Section 44AE (માલવાહક ગાડી) ની પોતાની શરતો છે; પ્રિઝમ્પ્ટિવ ફોર્મ વાપરતાં પહેલાં ચેક કરો.",
  "it.n_tax": "પ્રિઝમ્પ્ટિવ દર કરતાં ઓછો નફો જાહેર કરવા ચોપડા જોઈએ અને ઓડિટ જોઈ શકે: ત્યારે રિટર્ન ITR-3 છે.",
