  "ca.intro": "એક બિઝનેસ અને સમયગાળો ફક્ત વાંચી શકાય તેવી એક ફાઇલ (.nsca) માં ભરે છે. તે તમારા એકાઉન્ટન્ટને WhatsApp કે email થી મોકલો. તેઓ તેને ca.niveshsahayak.in પર ખોલે છે, ચોપડા વાંચે છે, સવાલ ઉમેરે છે અને તમને કૉમેન્ટ પાછી મોકલે છે.",
  "ca.notlive": "આ ફાઇલ આપવાની રીત છે, લાઇવ શેર કરેલું લોગિન નથી. તમારા એકાઉન્ટન્ટ ચોપડા ફાઇલ બનાવી ત્યારે જેવા હતા તેવા જુએ છે. લાઇવ લોગિન માટે તમારા ચોપડા રાખે તેવું સર્વર જોઈએ, અને Nivesh Sahayak પાસે એવું કોઈ નથી: તમારા ચોપડા તમારા ડિવાઇસ પર રહે છે. નવી એન્ટ્રી માટે નવી ફાઇલ બનાવો.",
  "ca.what": "શું જાય છે",
  "ca.earlier": "પહેલી તારીખ પહેલાંની એન્ટ્રી પણ (શરૂઆતના બેલેન્સ અને એજિંગ માટે જરૂરી)",
  "ca.items": "ખરીદ અને વેચાણ ભાવ સાથે આઇટમ લિસ્ટ (સ્ટોક માટે જરૂરી)",
  "ca.extra": "ફક્ત ટિક કરો તો",
  "ca.extrah": "ટિક ન કરો ત્યાં સુધી બહાર રહે છે. ચિત્રો (લોગો, સહી), તમારો PIN અને બેકઅપ સેટિંગ ક્યારેય સામેલ થતાં નથી.",
  "ca.orders": "ક્વોટેશન, પ્રોફોર્મા ઇન્વૉઇસ, સેલ્સ ઓર્ડર, ચલણ અને પરચેઝ ઓર્ડર",
  "ca.staff": "સેલેરી સ્લિપ, સ્ટાફ એડવાન્સ, લોન અને EMI, પેટી કેશ, અને કર્મચારી લિસ્ટ",
  "ca.phones": "પાર્ટીના ફોન નંબર, ઈ-મેલ સરનામાં અને WhatsApp નંબર",
  "ca.no.orders": "ક્વોટેશન અને ઓર્ડર",
  "ca.no.staff": "પગાર અને સ્ટાફના રેકોર્ડ",
  "ca.no.phones": "ફોન નંબર અને ઈ-મેલ સરનામાં",
  "ca.no.bank": "તમારા બેંક ખાતાની વિગત",
  "ca.note": "તમારા એકાઉન્ટન્ટ માટે નોંધ (મરજી મુજબ)",
  "ca.go": "ફાઇલ બનાવો",
  "ca.ready": "ફાઇલ તૈયાર: {n} એન્ટ્રી, {p} પાર્ટી, લગભગ {kb} KB.",
  "ca.code": "ચેક કોડ:",
  "ca.codeh": "આ કોડ તમારા મેસેજમાં મોકલો, કે કૉલ પર વાંચી સંભળાવો. તમારા એકાઉન્ટન્ટ તેને ફાઇલ બતાવે તે કોડ સાથે સરખાવે છે, એટલે રસ્તામાં બદલાયેલી ફાઇલ પકડાય છે.",
  "ca.notin": "આ ફાઇલમાં નથી: {w}.",
  "ca.nothing": "કંઈ બહાર રાખ્યું નથી",
  "ca.copymsg": "મેસેજ કૉપી કરો",
  "ca.copied": "મેસેજ કૉપી થયો",
  "ca.msgl": "ફાઇલ સાથે મોકલવાનો મેસેજ",
  "ca.msg": "{biz} ના ચોપડા {from} થી {to}. જોડેલી ફાઇલ {url} પર ખોલો (લોગિન વગર ચાલે છે, કંઈ અપલોડ થતું નથી). ચેક કોડ: {code}. આ આજે બનાવેલી ફક્ત વાંચવાની કૉપી છે; કૃપા કરીને તમારા સવાલ કૉમેન્ટ ફાઇલ તરીકે પાછા મોકલો.",
  "ca.how": "ફાઇલ WhatsApp કે ઈ-મેલથી અટેચમેન્ટ તરીકે મોકલો. WhatsApp નામના અંતે .nsca બતાવે તો નામ બદલશો નહીં.",
  "ca.cT": "CA ની કૉમેન્ટ",
  "ca.cIntro": "તમારા એકાઉન્ટન્ટ સવાલ અને કૉમેન્ટની નાની ફાઇલ (.nsca-comments) પાછી મોકલે છે. દરેક સવાલ તે જે એન્ટ્રી વિશે છે તેની બાજુમાં જોવા અહીં લોડ કરો. જવાબ આપો, બંધ માર્ક કરો, અને પાછી મોકલવા ફાઇલ ફરી સેવ કરો.",
  "ca.load": "કૉમેન્ટ ફાઇલ લોડ કરો",
