  "ca.unsealed": "આ ફાઇલમાં ચેકસમ નથી, એટલે રસ્તામાં થયેલો ફેરફાર દેખાશે નહીં.",
  "ca.badfile": "આ એકાઉન્ટન્ટ વ્યૂઅરની કૉમેન્ટ ફાઇલ નથી, કે તે બદલાઈ ગઈ છે.",
