  "ca.party": "પાર્ટી",
  "ca.screen": "સ્ક્રીન",
  "ca.general": "સામાન્ય કૉમેન્ટ",
  "cv.h1": "એકાઉન્ટન્ટ વ્યૂઅર: તમારા ક્લાયન્ટે મોકલેલી ચોપડાની ફાઇલ ખોલો",
  "cv.intro": "તમારા ક્લાયન્ટ એક સમયગાળાના ચોપડા એક ફાઇલમાં ભરીને તમને WhatsApp કે email થી મોકલે છે. તેને અહીં ખોલો અને વાંચો: બાકી, પાર્ટીઓ, ખાતાવહી, ડે બુક, GST ગણતરી, ફાઇનલ એકાઉન્ટ અને દરેક દસ્તાવેજ. શોધો અને ફિલ્ટર કરો, કોઈ પણ એન્ટ્રી પર સવાલ પૂછો, અને તમારી કૉમેન્ટ નાની ફાઇલ તરીકે પાછી મોકલો. મફત, લોગિન વગર, અને કંઈ અપલોડ થતું નથી: ફાઇલ તમારા બ્રાઉઝરમાં જ વંચાય છે.",
  "cv.drop": ".nsca ફાઇલ અહીં નાખો",
  "cv.choose": "ફાઇલ પસંદ કરો",
  "cv.dropnote": "ફાઇલ આ ડિવાઇસ પર રહે છે. અહીં કંઈ સેવ થતું નથી અને અહીંથી તમે ક્લાયન્ટના ચોપડા બદલી શકતા નથી.",
  "cv.nav.home": "ઝલક",
  "cv.docs": "દસ્તાવેજ",
  "cv.day": "ડે બુક",
  "cv.fin": "ફાઇનલ એકાઉન્ટ",
  "cv.gst": "GST ગણતરી",
  "cv.cT": "સવાલ અને કૉમેન્ટ",
  "cv.how.h": "આ કેવી રીતે ચાલે છે",
  "cv.how.1": "તમારા ક્લાયન્ટ Nivesh Sahayak ખોલે છે, મારો ડેટા, તમારા એકાઉન્ટન્ટને મોકલો માં જાય છે, અને એક બિઝનેસ અને સમયગાળા માટે \"મારા એકાઉન્ટન્ટ માટે ફાઇલ બનાવો\" પસંદ કરે છે.",
  "cv.how.2": "તેઓ તમને ફાઇલ (.nsca વાળી) અને એ જ મેસેજમાં ટૂંકો ચેક કોડ મોકલે છે.",
  "cv.how.3": "તમે આ પેજ પર ફાઇલ ખોલો છો. પેજ જણાવે છે કે ફાઇલ બદલાઈ નથી કે નહીં, અને સરખાવવા ક્લાયન્ટે આપેલો ચેક કોડ લખવા દે છે.",
  "cv.how.4": "ચોપડા વાંચો, શોધો, અને કોઈ પણ દસ્તાવેજ, ડે બુક એન્ટ્રી કે સ્ક્રીન પર \"સવાલ કે કૉમેન્ટ ઉમેરો\" દબાવો. તમે લખો તે બધું આ બ્રાઉઝરમાં રહે છે.",
  "cv.how.5": "પૂરું થાય ત્યારે \"સવાલ અને કૉમેન્ટ\" ખોલો અને નાની .nsca-comments ફાઇલ પાછી મોકલો. તમારા ક્લાયન્ટ તેને લોડ કરે છે અને દરેક સવાલ એન્ટ્રીની બાજુમાં જુએ છે. તેઓ જવાબ આપી શકે, અને તમે જવાબ અહીં લોડ કરી શકો.",
  "cv.live.h": "ફાઇલ આપવાની રીત, લાઇવ લોગિન નહીં",
  "cv.live.p": "આ ફાઇલ આપવાની રીત છે. તમે ક્લાયન્ટના ખાતામાં લોગિન કરતા નથી અને તેઓ પછી કરે તે ફેરફાર જોતા નથી. લાઇવ શેર કરેલા લોગિન માટે ચોપડા રાખે તેવું સર્વર જોઈએ, અને Nivesh Sahayak પાસે એવું કોઈ નથી: ચોપડા ક્લાયન્ટના ડિવાઇસ પર રહે છે. નવા સમયગાળા માટે કે સુધારા પછી ક્લાયન્ટ પાસેથી નવી ફાઇલ માગો.",
  "cv.safe.h": "ફાઇલમાં શું છે, અને શું નથી",
  "cv.safe.p": "તમારા ક્લાયન્ટ શું જાય તે ટિક કરે છે. ફાઇલમાં મૂળભૂત રીતે સમયગાળાના અંત સુધીની એક બિઝનેસની એન્ટ્રી, પાર્ટી અને આઇટમ હોય છે. ક્વોટેશન અને ઓર્ડર, પગાર અને સ્ટાફના રેકોર્ડ, ફોન નંબર અને ઈ-મેલ સરનામાં, અને બિઝનેસના બેંક ખાતાની વિગત ક્લાયન્ટ ટિક ન કરે ત્યાં સુધી બહાર રહે છે. ચિત્રો, PIN અને બેકઅપ સેટિંગ ક્યારેય સામેલ થતાં નથી. ફાઇલમાં ચેકસમ છે એટલે તેમાં કોઈ ફેરફાર થાય તો આ પેજ પર દેખાય છે. ફાઇલ બદલીને ફરી ગણતરી કરનારને ચેકસમ રોકી શકતો નથી, એટલે ચેક કોડ ક્લાયન્ટે અલગથી મોકલેલા કોડ સાથે સરખાવો.",
  "cv.readonly": "આ ફાઇલનું ફક્ત વાંચવાનું વ્યૂ છે: અહીં કંઈ બદલી કે સેવ કરી શકાતું નથી.",
  "cv.notfile": "આ Nivesh Sahayak ની એકાઉન્ટન્ટ ફાઇલ (.nsca) નથી.",
  "cv.iscomments": "આ કૉમેન્ટ ફાઇલ છે. પહેલાં ચોપડાની ફાઇલ (.nsca) ખોલો, પછી \"સવાલ અને કૉમેન્ટ\" માંથી કૉમેન્ટ લોડ કરો.",
  "cv.newer": "આ ફાઇલ નવા વર્ઝનથી બની છે. આ પેજ ફરી લોડ કરીને ફરી પ્રયત્ન કરો.",
  "cv.nostore": "તમારી કૉમેન્ટ આ બ્રાઉઝરમાં રાખી ન શકાઈ. હમણાં જ કૉમેન્ટ ફાઇલ સેવ કરો.",
  "cv.period": "સમયગાળો: {from} થી {to}",
  "cv.earlier": "પહેલાંની એન્ટ્રી સામેલ",
  "cv.made": "ફાઇલ {d} એ બની",
  "cv.fromowner": "તમારા ક્લાયન્ટની નોંધ:",
  "cv.sumok": "ફાઇલ બની ત્યારથી બદલાઈ નથી (તેનો ચેકસમ તેની સામગ્રી સાથે મેળ ખાય છે).",
  "cv.sumbad": "ફાઇલ તેના ચેકસમ સાથે મેળ ખાતી નથી.",
  "cv.sumbadh": "બન્યા પછી તે બદલાઈ કે બગડી ગઈ છે. તેના પર ભરોસો કરતાં પહેલાં ક્લાયન્ટને ફરી મોકલવા કહો.",
  "cv.code": "આ ફાઇલનો ચેક કોડ:",
