  "hm.h.creep.ok": "ખર્ચ વધે છે. રિપોર્ટ સ્ક્રીન પર કયો હેડ વધ્યો તે જુઓ.",
  "hm.h.creep.low": "ખર્ચ અચાનક વધ્યો. વધેલો હેડ શોધો, અને તે એક વખતનું બિલ તો નથી તે ચેક કરો.",
  "hm.h.creep.rule": "છેલ્લા પૂરા મહિનાનો ખર્ચ તેની પહેલાંના 3 મહિનાની સરેરાશ સામે. 5% કે ઓછો વધારો = 100, 40% કે વધુ વધારો = 0. એક વખતનું મોટું બિલ તેને એક મહિના માટે ઘટાડશે.",
  "hm.rm.t": "આ ડિવાઇસ પરના રિમાઇન્ડર",
  "hm.rm.p": "App ખોલો ત્યારે આજે શું કરવાનું છે તે બતાવે છે. સૌથી તાકીદની લાઇનો માટે ફોન નોટિફિકેશન પણ બતાવવા દઈ શકો છો, દરેક દિવસમાં એક વાર.",
  "hm.rm.on": "App ખોલું ત્યારે નોટિફિકેશન બતાવો",
  "hm.rm.nosupport": "આ બ્રાઉઝર નોટિફિકેશન સપોર્ટ કરતું નથી. મારો દિવસનું લિસ્ટ તો ચાલે જ છે.",
  "hm.rm.denied": "આ સાઇટ માટે નોટિફિકેશન બંધ છે. બ્રાઉઝરના સાઇટ સેટિંગમાં ચાલુ કરો, પછી બૉક્સ ફરી ટિક કરો.",
  "hm.rm.off": "નોટિફિકેશન બંધ છે.",
  "hm.rm.set": "નોટિફિકેશન ચાલુ છે. App ખોલશો ત્યારે સૌથી તાકીદની લાઇનો દેખાશે.",
  "hm.rm.title": "{b}: આજે તમારી જરૂર છે",
  "hm.rm.ics": "બાકી તારીખો ફોનના કૅલેન્ડરમાં મૂકો",
  "hm.rm.icsp": "આગલા 60 દિવસની કૅલેન્ડર ફાઇલ બનાવે છે: બિલની બાકી તારીખો અને ટેક્સની તારીખો. તમારા કૅલેન્ડરમાં ઉમેરવા ફોન પર ખોલો; તે App બંધ હોય ત્યારે પણ એક દિવસ પહેલાં જાતે વાગે છે.",
