  "hm.rm.lim": "બ્રાઉઝર શું ન કરી શકે",
  "hm.rm.l1": "બંધ વેબ પેજ ચાલી શકતું નથી, અને આ App પાછળ તમને પુશ મેસેજ મોકલે તેવું કોઈ સર્વર નથી. એટલે App નું રિમાઇન્ડર ફક્ત App ખોલો ત્યારે દેખાય છે.",
  "hm.rm.l2": "બધું તમારા ડિવાઇસ પર ગણાય છે, એટલે ઇન્ટરનેટ વગર ચાલે છે. તમારા બિઝનેસ વિશે કંઈ ક્યાંય મોકલાતું નથી.",
  "hm.rm.l3": "ચૂકવી ન શકાય તેવી તારીખો માટે કૅલેન્ડર ફાઇલ વાપરો: ફોનનું કૅલેન્ડર જાતે વાગે છે. તે આજનો ફોટો છે, એટલે નવાં બિલ નોંધ્યા પછી નવી ફાઇલ બનાવો.",
  "hm.rm.l4": "ઇન્સ્ટોલ કરેલી App માં, તમારો ફોન છૂટ આપે ત્યાં, આઇકન પરનો આંકડો કેટલાં તાકીદનાં કામ છે તે બતાવે છે.",
